+inline bool GetAttrValue(CpuKernelContext &ctx, const std::string &name, bool &value)
+{
+    auto attr = ctx.GetAttr(name);
+    if (!attr) {
+        KERNEL_LOG_ERROR("attr is null: %s", name.c_str());
+        return false;
+    }
+    value = attr->GetBool();
+    return true;
+}
