+    int32_t gSize_ = 0;
+    int32_t kSeqSize_ = 0;
+    int32_t kHeadNum_ = 0;
+    int32_t qHeadNum_ = 0;
+    int32_t s1BaseSize_ = 0;
+    int32_t s2BaseSize_ = 0;
+    int32_t kCacheBlockSize_ = 0;
+    int32_t maxBlockNumPerBatch_ = 0;
+
