+#ifndef QUANT_LIGHTNING_INDEXER_V2_VECTOR_H
+#define QUANT_LIGHTNING_INDEXER_V2_VECTOR_H
+
+#include "kernel_operator.h"
+#include "quant_lightning_indexer_v2_vector.h"
