+template <typename QLIV2T>
+__aicore__ inline void QLIV2Preload<QLIV2T>::InitBuffers()
+{
+    if ASCEND_IS_AIV {
+        vectorService.InitBuffers(pipe);
+    } else {
+        matmulService.InitBuffers(pipe);
+    }
+}
