+
+    for (uint16_t i = 0; i < vfLoop; ++i) {
+        MicroAPI::LoadAlign<uint16_t, MicroAPI::LoadDist::DIST_DINTLV_B8>(vregLow, vregHigh, inputBuf + i * 256);
